export interface CompositionApplyInput {
  projectId: string;
  compositionId: string;
  expectedVersion: number;
  changeId: string;
  /**
   * @minItems 1
   * @maxItems 256
   */
  operations: (
    | {
        op: 'replace';
        rootId: string;
        /**
         * @minItems 1
         * @maxItems 256
         */
        nodes: (
          | {
              id: string;
              kind: 'group';
              /**
               * @maxItems 256
               */
              children: string[];
              presentation?:
                | {
                    mode: 'tabs';
                  }
                | {
                    mode: 'split';
                    axis: 'horizontal' | 'vertical';
                    /**
                     * @minItems 2
                     * @maxItems 256
                     */
                    weights: number[];
                  };
            }
          | {
              id: string;
              component: string;
              version: string;
              props: {};
              bindings: {
                [k: string]:
                  | {
                      id: string;
                      version: string;
                    }
                  | {
                      documentId: string;
                      version: number;
                    }
                  | {
                      kind: 'live-document';
                      documentId: string;
                    };
              };
              /**
               * @maxItems 1000
               */
              selection?: string[];
              presentation?: {
                emphasis: 'normal' | 'highlight';
              };
              kind: 'view';
              protected?: boolean;
            }
        )[];
      }
    | {
        op: 'insert';
        parentId: string;
        index: number;
        node:
          | {
              id: string;
              kind: 'group';
              /**
               * @maxItems 256
               */
              children: string[];
              presentation?:
                | {
                    mode: 'tabs';
                  }
                | {
                    mode: 'split';
                    axis: 'horizontal' | 'vertical';
                    /**
                     * @minItems 2
                     * @maxItems 256
                     */
                    weights: number[];
                  };
            }
          | {
              id: string;
              component: string;
              version: string;
              props: {};
              bindings: {
                [k: string]:
                  | {
                      id: string;
                      version: string;
                    }
                  | {
                      documentId: string;
                      version: number;
                    }
                  | {
                      kind: 'live-document';
                      documentId: string;
                    };
              };
              /**
               * @maxItems 1000
               */
              selection?: string[];
              presentation?: {
                emphasis: 'normal' | 'highlight';
              };
              kind: 'view';
              protected?: boolean;
            };
      }
    | {
        op: 'move';
        id: string;
        parentId: string;
        index: number;
      }
    | {
        op: 'remove';
        id: string;
      }
    | {
        op: 'props';
        id: string;
        props: {};
      }
    | {
        op: 'bind';
        id: string;
        bindings: {
          [k: string]:
            | {
                id: string;
                version: string;
              }
            | {
                documentId: string;
                version: number;
              }
            | {
                kind: 'live-document';
                documentId: string;
              };
        };
      }
  )[];
}

