export interface FeedbackReadOutput {
  complete: boolean;
  contextVersion: 1;
  feedback: {
    anchor:
      | {
          documentId: string;
          from: number;
          kind: 'document';
          to: number;
          version: number;
        }
      | {
          /**
           * @minItems 1
           * @maxItems 1024
           */
          entities: string[];
          kind: 'table';
          resource: {
            id: string;
            version: string;
          };
        };
    annotation: {
      annotationId: string;
      messageId: string;
      submittedVersion: number;
    };
    author: string;
    messageDigest: string;
    messageText: string;
    source:
      | {
          entityKey: string;
          kind: 'table';
          namespace: string;
          resource: {
            id: string;
            version: string;
          };
          /**
           * @minItems 1
           * @maxItems 1024
           */
          rows: {
            [k: string]: string | number | boolean | null;
          }[];
        }
      | {
          from: number;
          kind: 'document';
          sha256: string;
          source: {
            dirty: boolean;
            documentId: string;
            kind: 'buffer';
            path: string;
            version: number;
          };
          text: string;
          to: number;
        };
  } | null;
  fetchReceipt: {
    at: string;
    bindingId: string;
    contextId: string;
    deliveryId: string;
    fetchId: string;
    nativeToolUseId: string | null;
    observation: 'owner-served' | 'client-tool-returned';
    principal: string;
    receiptId: string;
  };
  next: string | null;
  relatedDocumentId: string | null;
}

export interface FeedbackStatusInput {
  projectId: string;
  query: {
    after: number;
    cursor: string | null;
    limit: number;
    maxBytes: number;
  };
  submissionId: string;
  taskId: string;
}

export interface FeedbackStatusOutput {
  complete: boolean;
  /**
   * @minItems 0
   * @maxItems 128
   */
  fetches: {
    at: string;
    bindingId: string;
    contextId: string;
    deliveryId: string;
    fetchId: string;
    nativeToolUseId: string | null;
    observation: 'owner-served' | 'client-tool-returned';
    principal: string;
    receiptId: string;
  }[];
  next: string | null;
  queue: {
    attempts: number;
    enqueueAck: 'not-observed' | 'observed';
    inboxReceipt: {
      acceptedAt: string;
      deliveryId: string;
      emission: 'not-attempted' | 'attempt-recorded' | 'emitted' | 'unknown';
      inboxReceiptId: string;
      requestDigest: string;
    } | null;
    transport: 'not-attempted' | 'queued' | 'attempt-recorded' | 'accepted' | 'unknown' | 'blocked';
  };
  /**
   * @minItems 0
   * @maxItems 128
   */
  responses: {
    annotationId: string;
    author: string;
    fromAssignedBusiness: boolean;
    messageId: string;
    replyTo: string;
  }[];
  retention: {
    originalTargetPreserved: true;
    receipts: 'retained' | 'expired' | 'unavailable';
  };
  snapshot: {
    annotationVersion: number | null;
    deliveryStoreVersion: number;
  };
  submission: {
    annotation: {
      annotationId: string;
      messageId: string;
      submittedVersion: number;
    } | null;
    author: string;
    contextId: string | null;
    delivery: {
      adapterRegistrationId: string;
      contextId: string;
      deliveryId: string;
      externalSessionId: string;
      message: {
        annotationId: string;
        messageId: string;
        submittedVersion: number;
      };
      mode: 'post-tool-boundary' | 'queued-turn';
      projectId: string;
      requestDigest: string;
      targetBindingId: string;
      taskId: string;
      taskVersion: number;
    } | null;
    reason:
      | (
          | 'queue-full'
          | 'source-unavailable'
          | 'route-conflict'
          | 'owner-unavailable'
          | 'needs-routing'
          | 'context-limit'
        )
      | null;
    requestDigest: string;
    stages: {
      annotation: 'pending' | 'committed' | 'needs-reconcile';
      context: 'pending' | 'prepared' | 'needs-reconcile';
      queue: 'pending' | 'queued' | 'blocked' | 'needs-routing';
    };
    submissionId: string;
  };
}

